-- Queer Atlas: North America hotel batch 1
-- Cancun, Chicago, Dallas, Denver, Fire Island, Las Vegas, New Orleans,
-- Orlando, Palm Springs, Philadelphia, San Diego, Seattle and Washington DC.
-- Three researched LGBTQ+-focused or LGBTQ+-welcoming hotels per destination.
-- Editorial and source check: 2026-08-23.
--
-- No ratings or review totals are manufactured. "LGBTQ+-welcoming" is used only
-- where a current specialist LGBTQ+ directory or the property itself supplies
-- that signal. Coordinates identify the individual hotel building, not a city
-- centroid. Safe to run more than once; city + hotel name is the natural key.

begin;

alter table if exists public.places
  add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
  select *
  from jsonb_to_recordset($hotels$
[
 {"name":"Presidente InterContinental Cancun Resort","city":"cancun","description":"A polished beachfront resort on the calmer northern stretch of Cancun's Hotel Zone. Its current Travel Gay Approved listing makes it a documented LGBTQ+-welcoming full-service option with beach, pools, spa and resort dining.","vibe":"welcoming beachfront luxury on a calm Caribbean bay","tags_csv":"luxury,relax,mixed","hours":"Hotel reception operates 24 hours; restaurants, spa, pools and beach services follow current resort schedules.","link":"https://presidenteiccancun.com/en/home/","location":"Boulevard Kukulcan Km 7.5, Zona Hotelera, 77500 Cancun, Quintana Roo, Mexico","lat":21.13545757,"lng":-86.75445776,"arrival":"Standard resort check-in; allow extra time on holiday weekends and reserve spa or dining separately.","best_for":"A quiet-water beach stay with Hotel Zone access rather than an adults-only party hotel.","audience":"LGBTQ+ travellers, couples, families and international resort guests in a broad mixed setting.","dress":"Resort casual by day; restaurants and spa areas apply their own practical rules.","inclusion":"The resort has a current Travel Gay Approved listing and publishes a Pride-oriented welcome page.","basis":"Current Travel Gay Approved listing plus the resort's own Pride welcome content.","hotel_class":"Luxury beachfront resort","coordinate_source":"Mapbox hotel POI checked against the official Km 7.5 address.","source_urls":["https://www.travelgay.com/gay-cancun-hotels","https://presidenteiccancun.com/hotel-presidente-intercontinental-cancun-resort/"]},
