$hotels$) h(
    name text, city text, description text, vibe text, tags_csv text,
    hours text, link text, location text, lat double precision, lng double precision,
    arrival text, best_for text, audience text, dress text, inclusion text,
    basis text, hotel_class text, coordinate_source text, source_urls jsonb
  )
), source_hotels as (
  select
    h.*,
    jsonb_build_object(
      'queue_wait', h.arrival,
      'best_nights', h.best_for,
      'crowd_mix', h.audience,
      'dress_code', h.dress,
      'staff_inclusivity', h.inclusion,
      'inclusion_basis', h.basis,
      'hotel_class', h.hotel_class,
      'coordinate_source', h.coordinate_source,
      'source_urls', h.source_urls,
      'research_status', 'researched_sources_and_exact_property_location',
      'updated_at', '2026-08-23T00:00:00Z'
    ) as intel
  from raw_hotels h
), updated as (
  update public.places p
  set type = 'hotel',
      description = h.description,
      vibe = h.vibe,
      vibe_tags = string_to_array(h.tags_csv, ','),
      hours = h.hours,
      link = h.link,
      location = h.location,
      lat = h.lat,
      lng = h.lng,
      venue_intel = coalesce(p.venue_intel, '{}'::jsonb) || h.intel,
      seo_indexable = true,
      seo_quality_status = 'approved',
      updated_at = timezone('utc', now())
  from source_hotels h
  where lower(trim(p.city)) = h.city
    and lower(trim(p.name)) = lower(trim(h.name))
  returning p.id
)
insert into public.places (
  name, city, type, description, vibe, vibe_tags, hours, link, location,
  lat, lng, venue_intel, seo_indexable, seo_quality_status, updated_at
)
select
  h.name, h.city, 'hotel', h.description, h.vibe,
  string_to_array(h.tags_csv, ','), h.hours, h.link, h.location,
  h.lat, h.lng, h.intel, true, 'approved', timezone('utc', now())
from source_hotels h
where not exists (
  select 1 from public.places p
  where lower(trim(p.city)) = h.city
    and lower(trim(p.name)) = lower(trim(h.name))
);

commit;

-- Expected: 3 complete rows in every destination.
select
  city,
  count(*) filter (
    where type = 'hotel'
      and venue_intel->>'updated_at' = '2026-08-23T00:00:00Z'
  ) as batch_hotels,
  count(*) filter (
    where type = 'hotel'
      and venue_intel->>'updated_at' = '2026-08-23T00:00:00Z'
      and coalesce(venue_intel->>'queue_wait', '') <> ''
      and coalesce(venue_intel->>'best_nights', '') <> ''
      and coalesce(venue_intel->>'crowd_mix', '') <> ''
      and coalesce(venue_intel->>'dress_code', '') <> ''
      and coalesce(venue_intel->>'staff_inclusivity', '') <> ''
      and jsonb_array_length(coalesce(venue_intel->'source_urls', '[]'::jsonb)) >= 2
      and lat between -90 and 90
      and lng between -180 and 180
      and coalesce(location, '') <> ''
      and coalesce(link, '') <> ''
  ) as complete_rows
from public.places
where lower(trim(city)) in (
  'cancun','chicago','dallas','denver','fireisland','las_vegas','new_orleans',
  'orlando','palm_springs','philadelphia','san_diego','seattle','washington_dc'
)
group by city
order by city;

select
  name, city, location,
  round(lat::numeric, 6) as lat,
  round(lng::numeric, 6) as lng,
  venue_intel->>'inclusion_basis' as inclusion_basis
from public.places
where type = 'hotel'
  and venue_intel->>'updated_at' = '2026-08-23T00:00:00Z'
order by city, name;
